import{fa as o,h as n,o as r}from"./chunk-TOTCSGX5.js";var t=class i{newsSignal=r([{id:1,title:"Top Modelos EV Chinos en M\xE9xico: BYD, MG y JAC",summary:"An\xE1lisis de la oferta actual: del BYD Dolphin urbano al MG4 para volumen masivo",content:"Las marcas chinas est\xE1n redefiniendo el mercado mexicano con una combinaci\xF3n de innovaci\xF3n y precio. BYD apuesta por el Yuan Plus para flotas corporativas y el Dolphin para la penetraci\xF3n urbana. MG impulsa el MG4 Electric con alta elasticidad de demanda, mientras que JAC domina la \xFAltima milla con el E10X, el el\xE9ctrico m\xE1s accesible ensamblado en Hidalgo.",imageUrl:"https://images.unsplash.com/photo-1617788138017-80ad40651399?w=600&h=400&fit=crop",category:"Automotriz",author:"Carlos M\xE9ndez",date:new Date("2024-12-02"),readTime:6,tags:["BYD","MG","Electromovilidad"]},{id:2,title:"Aranceles y Normatividad: El reto de importar EVs",summary:"Impacto del 20% de arancel a veh\xEDculos chinos sin tratado comercial",content:"Desde octubre de 2024, los veh\xEDculos el\xE9ctricos chinos enfrentan un arancel general del 15% al 20% al no contar con un Tratado de Libre Comercio. A diferencia de las unidades del T-MEC, estas marcas deben pagar IVA y cumplir con la NOM-194 de seguridad. JAC mitiga esto mediante el ensamblaje local (CKD) para reducir la exposici\xF3n a variaciones arancelarias.",imageUrl:"https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?w=600&h=400&fit=crop",category:"Econom\xEDa",author:"Redacci\xF3n Legal",date:new Date("2024-12-02"),readTime:5,tags:["Impuestos","Aduanas","T-MEC"]},{id:3,title:'Cultura de Negocios con China: El valor del "Guanxi"',summary:"C\xF3mo negociar exitosamente entendiendo las jerarqu\xEDas y valores asi\xE1ticos",content:"Para empresas como BYD o SAIC, el concepto de guanxi o confianza a largo plazo es prioritario. La comunicaci\xF3n debe ser formal y paciente, ya que la toma de decisiones suele ser jer\xE1rquica. A diferencia de occidente, los contratos en China se ven como marcos de cooperaci\xF3n flexibles que pueden revisarse si el contexto cambia.",imageUrl:"https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=600&h=400&fit=crop",category:"Negocios",author:"Ana Rodr\xEDguez",date:new Date("2024-12-01"),readTime:4,tags:["Cultura","Negociaci\xF3n","China"]},{id:4,title:"Amazon vs. Mercado Libre: Choque de Estrategias",summary:"Eficiencia global de Amazon contra la adaptaci\xF3n local de Mercado Libre",content:"La expansi\xF3n del e-commerce presenta dos modelos opuestos. Amazon replica su modelo global basado en eficiencia, infraestructura y membres\xEDas Prime. Por otro lado, Mercado Libre apuesta por la regionalizaci\xF3n profunda, desarrollando soluciones espec\xEDficas para la informalidad y la falta de bancarizaci\xF3n que caracterizan a Latinoam\xE9rica.",imageUrl:"https://images.unsplash.com/photo-1523474253046-8cd2748b5fd2?w=600&h=400&fit=crop",category:"E-commerce",author:"Tech Insights",date:new Date("2024-12-02"),readTime:7,tags:["Estrategia","Latam","Competencia"]},{id:5,title:"La Batalla Log\xEDstica: \xDAltima Milla en Latam",summary:"Mercado Env\xEDos entrega el 75% de paquetes en menos de 48 horas",content:"La log\xEDstica es el eje del \xE9xito en la regi\xF3n. Mercado Libre construy\xF3 una red propia de fulfillment que cubre casi todo el territorio, logrando tiempos de entrega r\xE9cord. Amazon respondi\xF3 inaugurando en 2023 su mayor centro log\xEDstico en CDMX. Ambas empresas invierten fuertemente en tecnolog\xEDa para superar la inseguridad y las direcciones complejas.",imageUrl:"https://images.unsplash.com/photo-1586864387967-d02ef85d93e8?w=600&h=400&fit=crop",category:"Log\xEDstica",author:"Marco Ferrari",date:new Date("2024-11-30"),readTime:5,tags:["Env\xEDos","Supply Chain","Fulfillment"]},{id:6,title:"Fintech: La Revoluci\xF3n de Mercado Pago",summary:"Integraci\xF3n de servicios financieros para la poblaci\xF3n no bancarizada",content:"Mercado Pago evolucion\xF3 de una simple pasarela a un banco digital completo, ofreciendo cr\xE9ditos y billeteras a millones de usuarios no bancarizados. Esta vertical financiera es una ventaja competitiva clave que Amazon, limitada a alianzas con bancos tradicionales, no ha podido replicar con la misma profundidad en el mercado masivo.",imageUrl:"https://images.unsplash.com/photo-1601597111158-2fceff292cdc?w=600&h=400&fit=crop",category:"Finanzas",author:"Laura Schmidt",date:new Date("2024-11-29"),readTime:6,tags:["Fintech","Bancos","Pagos"]},{id:7,title:"Liderazgo y Cultura: Silicon Valley vs. Buenos Aires",summary:"Diferencias en gesti\xF3n y resoluci\xF3n de conflictos corporativos",content:"Amazon lleg\xF3 con un estilo directo, racional y basado en m\xE9tricas duras. Mercado Libre opera con un estilo m\xE1s relacional, flexible y emp\xE1tico. En el entorno latinoamericano, donde las emociones influyen en los negocios, el enfoque humano de Mercado Libre ha facilitado una conexi\xF3n m\xE1s natural para retener talento y negociar con socios.",imageUrl:"https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=600&h=400&fit=crop",category:"Management",author:"RRHH Global",date:new Date("2024-11-28"),readTime:8,tags:["Liderazgo","RRHH","Cultura"]},{id:8,title:"Historia: La Guerra del Banano y la UE",summary:"Discriminaci\xF3n hist\xF3rica a favor de las excolonias europeas",content:"Durante los a\xF1os 90 y 2000, la Uni\xF3n Europea impuso un sistema de cuotas que favorec\xEDa a los pa\xEDses de \xC1frica, Caribe y Pac\xEDfico, discriminando al banano latinoamericano. Esto gener\xF3 una estructura desigual donde Ecuador, pese a ser m\xE1s eficiente, enfrentaba aranceles punitivos que amenazaban el empleo de dos millones de personas.",imageUrl:"https://images.unsplash.com/photo-1528825871115-3581a5387919?w=600&h=400&fit=crop",category:"Historia",author:"Archivo Hist\xF3rico",date:new Date("2024-12-01"),readTime:6,tags:["Banano","UE","Proteccionismo"]},{id:9,title:"Victoria Legal en la OMC: El Acuerdo de Ginebra",summary:"C\xF3mo Ecuador venci\xF3 el proteccionismo europeo con derecho internacional",content:"Ecuador llev\xF3 el caso ante la Organizaci\xF3n Mundial del Comercio argumentando discriminaci\xF3n y gan\xF3. El conflicto culmin\xF3 con el Acuerdo de Ginebra en 2009, donde la UE se comprometi\xF3 a reducir progresivamente el arancel de 176 a 114 euros por tonelada, permitiendo a Ecuador recuperar competitividad y mercado sin trato desigual.",imageUrl:"https://images.unsplash.com/photo-1505664194779-8beaceb93744?w=600&h=400&fit=crop",category:"Legal",author:"Thomas Weber",date:new Date("2024-11-28"),readTime:7,tags:["OMC","Derecho","Diplomacia"]},{id:10,title:"Sostenibilidad: La Nueva Era del Banano",summary:"Transformaci\xF3n del sector hacia pr\xE1cticas ecol\xF3gicas certificadas",content:"La presi\xF3n europea y el fin del conflicto impulsaron una modernizaci\xF3n ecol\xF3gica. Hoy, certificaciones como Rainforest Alliance son la norma en Ecuador. Se prioriz\xF3 el uso racional del agua y el control de plagas. Lo que comenz\xF3 como una barrera comercial se convirti\xF3 en una ventaja competitiva basada en la calidad y el respeto al medio ambiente.",imageUrl:"https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=600&h=400&fit=crop",category:"Sostenibilidad",author:"Agro Futuro",date:new Date("2024-12-02"),readTime:5,tags:["Ecolog\xEDa","Certificaciones","Campo"]}]);allNews=o(()=>this.newsSignal());featuredNews=o(()=>this.newsSignal().slice(0,3));getNewsById(e){return this.newsSignal().find(a=>a.id===e)}getNewsByCategory(e){return o(()=>this.newsSignal().filter(a=>a.category===e))}static \u0275fac=function(a){return new(a||i)};static \u0275prov=n({token:i,factory:i.\u0275fac,providedIn:"root"})};export{t as a};
